const rupee = (n) => "\u20B9" + Number(n || 0).toLocaleString("en-IN");
const slug = (s) => "p_" + s.toLowerCase().trim().replace(/[^a-z0-9]+/g, "_").replace(/^_+|_+$/g, "") + "_" + Math.random().toString(36).slice(2, 6);
function waConfirmationLink(order) {
  const digits = (order.customer.phone || "").replace(/[^0-9]/g, "");
  const withCountry = digits.length === 10 ? "91" + digits : digits;
  const itemLines = order.items.map((it) => `- ${it.name} (${it.label}) x${it.qty}`).join("\n");
  const msg =
    `Hi ${order.customer.name}, your Amrit order ${order.orderCode || order.id} is confirmed!\n\n` +
    `${itemLines}\n\nTotal: ${rupee(order.total)} (${order.paymentMethod === "cod" ? "Cash on Delivery" : order.paymentMethod === "card" ? "Card" : "UPI"})\n\n` +
    `We'll let you know once it ships. Thank you for shopping with Amrit!`;
  return `https://wa.me/${withCountry}?text=${encodeURIComponent(msg)}`;
}
async function sha256Hex(text) {
  const enc = new TextEncoder().encode(text);
  const buf = await crypto.subtle.digest("SHA-256", enc);
  return Array.from(new Uint8Array(buf)).map((b) => b.toString(16).padStart(2, "0")).join("");
}

